import React, { useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import * as GaussianSplats3D from "@mkkellogg/gaussian-splats-3d";

const SplatPage = () => {
  const navigate = useNavigate();
  const containerRef = useRef(null);
  const viewerRef = useRef(null);
  const mountedRef = useRef(true);

  useEffect(() => {
    mountedRef.current = true;
    const container = containerRef.current;
    if (!container) return;

    const viewer = new GaussianSplats3D.Viewer({
      rootElement: container,
      selfDrivenMode: true,
      sharedMemoryForWorkers: false,
      cameraUp: [0, -1, 0],
      initialCameraPosition: [0, -0.6, 3],
      initialCameraLookAt: [0, -0.6, 0],
    });

    viewerRef.current = viewer;

    viewer
      .addSplatScene(process.env.PUBLIC_URL + "/my_table.splat")
      .then(() => {
        if (mountedRef.current) viewer.start();
      })
      .catch(() => {});

    return () => {
      mountedRef.current = false;
      viewerRef.current = null;
      try { viewer.stop(); } catch (_) {}
      // React removes the container from DOM automatically, taking the canvas with it.
      // Calling viewer.dispose() causes a removeChild race condition, so we skip it.
    };
  }, []);

  return (
    <div style={{ width: "100vw", height: "100vh", background: "#111", position: "relative" }}>
      <div ref={containerRef} style={{ width: "100%", height: "100%" }} />
      <div style={{ position: "absolute", top: "20px", left: "20px", zIndex: 10 }}>
        <button
          onClick={() => navigate(-1)}
          style={{
            background: "rgba(255,255,255,0.15)",
            border: "1px solid rgba(255,255,255,0.3)",
            color: "#fff",
            padding: "8px 16px",
            borderRadius: "8px",
            cursor: "pointer",
            backdropFilter: "blur(8px)",
            fontSize: "14px",
          }}
        >
          ← Back
        </button>
      </div>
      <div style={{ position: "absolute", bottom: "20px", left: "50%", transform: "translateX(-50%)", color: "rgba(255,255,255,0.4)", fontSize: "13px", zIndex: 10 }}>
        Drag to orbit · Scroll to zoom · Right-click to pan
      </div>
    </div>
  );
};

export default SplatPage;
